import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices, vatSummary } from '../src/reports.js';

test('overdueInvoices returns invoices with dueDate before asOf', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-01-15',
      dueDate: '2026-02-14',
      status: 'issued',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 10,
          unitPrice: 9500,
          vatRate: 21,
          discountPercent: 0,
        },
      ],
    },
  ];

  const result = overdueInvoices(invoices, '2026-03-01');

  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-2026-0001');
});

